package com.ordermanagement.chat.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * Incoming request for the chatbot endpoint.
 *
 * sessionId  – UUID generated by the browser on first message; sent back
 *              with every subsequent message so the server can recall history.
 * message    – The user's typed message (1-1000 chars).
 */
public record ChatRequest(

        /** Null on the very first message; the server will create and return a new one. */
        String sessionId,

        @NotBlank(message = "Message cannot be empty")
        @Size(max = 1000, message = "Message too long (max 1000 characters)")
        String message
) {}

